  padding: 16px;
}

/* ── Pixel Box ─────────────────────────────────────────────────────────── */

.pixel-box {
  background: var(--bg-box);
  border: 4px solid var(--gold);
  box-shadow:
    6px 6px 0 var(--gold-dark),
    0 0 50px rgba(255, 215, 0, 0.07);
  padding: 24px;
  width: 100%;
  max-width: 460px;
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  scrollbar-width: none;
}

.pixel-box::-webkit-scrollbar { display: none; }

/* ── Title ─────────────────────────────────────────────────────────────── */

.title-block {
  text-align: center;
  margin-bottom: 24px;
}

.game-title {
  font-size: 34px;
  line-height: 1.45;
  color: var(--gold);
  text-shadow:
    3px 3px 0 #b8860b,
    6px 6px 0 var(--gold-dark),
    9px 9px 0 rgba(0,0,0,0.5);
  letter-spacing: 6px;
  margin-bottom: 10px;
}

.game-subtitle {
  font-size: 7px;
  color: var(--green);
  letter-spacing: 3px;
  opacity: 0.75;
}

/* ── Name Section ──────────────────────────────────────────────────────── */

.name-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
}

.pixel-label {
  font-size: 8px;
  color: #999;
  letter-spacing: 1px;
}

.pixel-input {
  font-family: 'Press Start 2P', monospace;
  background: #030310;
  color: var(--green);
  border: 3px solid var(--green);
  padding: 11px 12px;
  font-size: 12px;
  width: 100%;
  outline: none;
  letter-spacing: 3px;
  caret-color: var(--green);
  text-transform: uppercase;
  transition: box-shadow 0.15s;
}

.pixel-input:focus {
  box-shadow: 0 0 18px rgba(0,255,65,0.28), inset 0 0 8px rgba(0,255,65,0.04);
}

.pixel-input::placeholder {
  color: #184018;
  letter-spacing: 1px;
}

/* ── Buttons ───────────────────────────────────────────────────────────── */

.pixel-btn {
  font-family: 'Press Start 2P', monospace;
  background: var(--gold);
  color: var(--bg);
  border: none;
  padding: 13px 16px;
  font-size: 10px;
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--gold-dark);
  letter-spacing: 1px;
  width: 100%;
  transition: transform 0.06s, box-shadow 0.06s;
  -webkit-font-smoothing: none;
}

.pixel-btn:hover:not(:disabled) {
  transform: translate(-1px, -1px);
  box-shadow: 5px 5px 0 var(--gold-dark);
}

.pixel-btn:active:not(:disabled) {
  transform: translate(3px, 3px);
  box-shadow: 1px 1px 0 var(--gold-dark);
}

.pixel-btn:disabled {
  background: #282828;
  color: #555;
  box-shadow: 4px 4px 0 #111;
  cursor: not-allowed;
}

.pixel-btn-alt {
  background: var(--bg-box);
  color: var(--gold);
  border: 3px solid var(--gold);
}

.pixel-btn-alt:hover:not(:disabled) {
  background: #191950;
}

/* ── How to Play ───────────────────────────────────────────────────────── */

.how-to-play {
  margin-bottom: 20px;
}

.section-label {
  font-size: 8px;
  color: #777;
  letter-spacing: 3px;
  text-align: center;
  margin-bottom: 10px;
  padding-bottom: 7px;
  border-bottom: 2px solid #1c1c40;
}

.how-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  background: #050518;
  border: 2px solid #181838;
}

.how-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.how-emojis {
  font-size: 14px;
  letter-spacing: 1px;
}

.how-desc {
  font-family: 'Press Start 2P', monospace;
  font-size: 7px;
  color: #aaa;
  text-align: right;
  line-height: 1.6;
  white-space: nowrap;
}

/* ── Leaderboard ───────────────────────────────────────────────────────── */

.leaderboard { margin-top: 4px; }

.lb-entry {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 6px;
  font-size: 8px;
  border-bottom: 1px solid #131330;
  color: #555;
}

.lb-entry.gold   { color: var(--gold); }
.lb-entry.silver { color: #c0c0c0; }
.lb-entry.bronze { color: #cd7f32; }
.lb-entry.current {
  color: var(--green) !important;
  background: rgba(0,255,65,0.05);
  border-color: rgba(0,255,65,0.12);
}

.lb-rank  { width: 28px; font-size: 14px; flex-shrink: 0; line-height: 1; }
.lb-name  { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lb-score { flex-shrink: 0; }

/* ── Screen wrapper ────────────────────────────────────────────────────── */

.screen {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
}

/* ── Game Canvas ───────────────────────────────────────────────────────── */

.game-canvas {
  display: block;
  border: 4px solid var(--gold);
  box-shadow:
    8px 8px 0 var(--gold-dark),
    0 0 60px rgba(255,215,0,0.1);
  cursor: none;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  max-width: calc(100vw - 16px);
  max-height: calc(100vh - 16px);
}

/* ── Game Over Screen ──────────────────────────────────────────────────── */

.gameover-title {
  font-size: 20px;
  color: var(--red);
  text-shadow: 3px 3px 0 #800000, 6px 6px 0 #3a0000;
  text-align: center;
  margin-bottom: 10px;
  letter-spacing: 4px;
  animation: blink 0.85s step-end infinite;
}

@keyframes blink {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0; }
}

.gameover-player {
  font-size: 10px;
  color: var(--green);
  text-align: center;
  margin-bottom: 6px;
  letter-spacing: 2px;
}

.gameover-score {
  font-size: 18px;
  color: var(--gold);
  text-align: center;
  text-shadow: 2px 2px 0 var(--gold-dark);
  margin-bottom: 16px;
}

.rank-announce {
  font-size: 9px;
  color: var(--gold);
  text-align: center;
  margin-bottom: 14px;
  padding: 8px;
  border: 2px solid var(--gold);
  background: rgba(255,215,0,0.06);
  animation: blink 0.55s step-end infinite;
}

.gameover-btns {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 20px;
}
